package com.mutqin.app

data class TajweedLesson(
  val id: Int, val title: String, val objective: String, val definition: String,
  val rule: String, val examples: List<String>, val practice: String,
  val commonMistake: String, val references: String
)

val tajweedLessons = listOf(
  TajweedLesson(1,"مدخل إلى علم التجويد","أن يعرف المتعلم معنى التجويد وهدفه.","التجويد لغةً التحسين، واصطلاحًا إعطاء الحروف حقها ومستحقها عند تلاوة القرآن.","يتعلم القارئ إخراج كل حرف من مخرجه، وإعطاءه صفاته، ومراعاة أحكام التلاوة بالمشافهة والتلقي.",listOf("التمييز بين س وص","التمييز بين ت و ط"),"اقرأ الفاتحة على معلّم، واطلب منه تحديد حرف واحد يحتاج إلى تحسين.","اعتبار معرفة أسماء الأحكام وحدها إتقانًا للتلاوة؛ فالأداء يحتاج تدريبًا وسماعًا.","المقدمة الجزرية، باب التجويد."),
  TajweedLesson(2,"الاستعاذة قبل القراءة","أن يميّز المتعلم صيغة الاستعاذة وموضعها.","الاستعاذة هي الالتجاء إلى الله من الشيطان الرجيم، وصيغتها المشهورة: أعوذ بالله من الشيطان الرجيم.","يشرع للقارئ أن يأتي بالاستعاذة عند ابتداء القراءة، ويجهر بها أو يسر بحسب الحال ومقام القراءة.",listOf("أعوذ بالله من الشيطان الرجيم"),"تدرّب على نطق الاستعاذة بوضوح دون استعجال، ثم ابدأ سورة قصيرة.","وصل الاستعاذة بكلام القارئ أو إسقاطها من غير معرفة موضعها وأحكام الابتداء.","سورة النحل: 98؛ كتب القراءات والتجويد في باب الاستعاذة."),
  TajweedLesson(3,"البسملة وأول السورة","أن يعرف المتعلم موضع البسملة عند ابتداء السور.","البسملة هي قول: بسم الله الرحمن الرحيم.","يبدأ القارئ أوائل السور بالبسملة، ما عدا سورة التوبة؛ ولها أوجه معروفة عند وصل آخر السورة بأول التالية، تدرس بالمشافهة.",listOf("بسم الله الرحمن الرحيم"),"اقرأ أول سورة الإخلاص بالبسملة، ثم تعرّف مع معلّمك على أوجه الانتقال بين سورتين.","إثبات البسملة في أول سورة التوبة أو تطبيق أوجه الوصل دون تعلمها.","كتب التجويد والقراءات، باب البسملة بين السورتين."),
  TajweedLesson(4,"مراتب القراءة","أن يفرق المتعلم بين التحقيق والحدر والتدوير.","مراتب الأداء المشهورة: التحقيق، والحدر، والتدوير؛ وهي تتعلق بسرعة القراءة مع مراعاة أحكام التجويد.","لا تخرج أي مرتبة عن صحة الحروف والحركات والمدود والغنن؛ فالسرعة لا تبرر الإخلال.",listOf("التحقيق: قراءة متأنية","الحدر: أسرع مع ضبط الأحكام","التدوير: توسط بينهما"),"اقرأ مقطعًا قصيرًا ببطء مضبوط، ثم بسرعة معتدلة دون إسقاط حرف أو حركة.","الخلط بين الحدر والإسراع المخلّ الذي يذهب الحروف أو الأحكام.","المقدمة الجزرية وشروحها، أبواب مراتب القراءة."),
  TajweedLesson(5,"مخارج الحروف: نظرة عامة","أن يعرف المتعلم المخارج العامة الخمسة.","المخرج هو الموضع الذي ينشأ منه صوت الحرف ويتميز به عن غيره.","المخارج العامة خمسة: الجوف، والحلق، واللسان، والشفتان، والخيشوم؛ وتفصيل المخارج يؤخذ بالتلقي.",listOf("الجوف لحروف المد","الحلق لحروفه","اللسان لأكثر الحروف","الشفتان لبعضها","الخيشوم للغنة"),"انطق أمثلة متنوعة، وحاول ملاحظة موضع خروج الصوت مع معلّم أو تسجيل تعليمي موثوق.","الاعتماد على شكل الحرف المكتوب بدل ملاحظة موضع النطق.","المقدمة الجزرية، باب مخارج الحروف."),
  TajweedLesson(6,"مخرج الجوف وحروف المد","أن يحدد المتعلم حروف المد ومخرجها العام.","الجوف هو الخلاء الممتد داخل الفم والحلق، ومنه تخرج حروف المد الثلاثة.","حروف المد: الألف الساكنة المفتوح ما قبلها، والواو الساكنة المضموم ما قبلها، والياء الساكنة المكسور ما قبلها.",listOf("قَالَ","يَقُولُ","قِيلَ"),"ميّز حرف المد في الأمثلة، واقرأها بمد طبيعي من غير تكلف.","تحويل حرف المد إلى حركة قصيرة أو المبالغة في إطالته دون سبب.","المقدمة الجزرية، باب مخارج الحروف والمدود."),
  TajweedLesson(7,"مخرج الحلق وحروفه","أن يرتب المتعلم حروف الحلق الستة.","للحلق ثلاثة مواضع إجمالية: أقصاه ووسطه وأدناه.","حروف الحلق ستة: الهمزة والهاء من أقصاه، والعين والحاء من وسطه، والغين والخاء من أدناه.",listOf("أَنعَمتَ","هُدًى","عَلِيم","حَكِيم","غَفُور","خَبِير"),"اقرأ الحروف الستة منفردة ثم في كلماتها، مع ملاحظة موضع الصوت دون ضغط الحلق.","تقريب الحاء إلى الهاء أو العين إلى الهمزة؛ صحح ذلك بالسماع من معلّم.","المقدمة الجزرية، باب مخارج الحروف."),
  TajweedLesson(8,"مخرج الشفتين","أن يميّز المتعلم حروف الشفتين.","للشفتين مخرجان تفصيليان مشهوران: بطن الشفة السفلى مع أطراف الثنايا العليا للفاء، وما بين الشفتين للواو غير المدية والباء والميم.","الفاء تخرج من باطن الشفة السفلى مع أطراف الثنايا العليا، والباء والميم والواو غير المدية من بين الشفتين.",listOf("فَتْح","بِسْم","مَال","وَعَد"),"قارن نطق فاء وباء وميم وواو في كلمات واضحة، دون مبالغة في ضم الشفتين.","إخراج الفاء من بين الشفتين أو إخفاء إطباق الشفتين في الباء والميم.","المقدمة الجزرية، باب مخارج الحروف."),
  TajweedLesson(9,"النون الساكنة والتنوين: التعريف","أن يتعرف المتعلم النون الساكنة والتنوين ومواضعهما.","النون الساكنة نون خالية من الحركة، ثابتة لفظًا وخطًا؛ والتنوين نون ساكنة زائدة تلحق آخر الاسم لفظًا لا خطًا.","لهما أربعة أحكام عند وقوعهما قبل الحروف: الإظهار، والإدغام، والإقلاب، والإخفاء.",listOf("مِنْ هَادٍ","عَلِيمٌ حَكِيمٌ","مِنْ بَعْدِ"),"استخرج النون الساكنة أو التنوين من أمثلة قرآنية، ثم حدد الحرف الذي يليهما.","الخلط بين النون الأصلية والتنوين أو الحكم على الكلمة دون النظر إلى الحرف التالي.","تحفة الأطفال، باب أحكام النون الساكنة والتنوين."),
  TajweedLesson(10,"الإظهار الحلقي","أن يحدد المتعلم حروف الإظهار ويطبق النطق الواضح.","الإظهار الحلقي هو إخراج النون الساكنة أو التنوين واضحين من غير إدغام ولا إخفاء عند حروف الحلق.","حروفه ستة: الهمزة والهاء والعين والحاء والغين والخاء؛ فإذا جاء أحدها بعد النون الساكنة أو التنوين أُظهرت النون أو التنوين.",listOf("مِنْ أَهْلِ","مِنْ هَادٍ","أَنْعَمْتَ","عَلِيمٌ حَكِيمٌ","مِنْ غِلٍّ","مِنْ خَيْرٍ"),"اقرأ الأمثلة وحدد حرف الإظهار، ثم سجّل قراءتك واستمع إليها أو اعرضها على معلّم.","إدخال صوت النون في الحرف التالي أو المبالغة في فصل الصوتين بما يخل بسلاسة القراءة.","تحفة الأطفال، باب أحكام النون الساكنة والتنوين؛ شروحها المعتمدة.")

  ,TajweedLesson(11,"الإدغام بغنة","أن يتعرف المتعلم حروف الإدغام المصحوب بالغنة.","الإدغام إدخال النون الساكنة أو التنوين في الحرف الذي يليهما حتى يصيرا كحرف واحد مشدد.","حروف الإدغام بغنة أربعة مجموعة في كلمة ينمو: الياء والنون والميم والواو، ويكون غالبًا من كلمتين.",listOf("مَنْ يَعْمَلْ","مِنْ وَالٍ","مِنْ مَالٍ","مِنْ نِعْمَةٍ"),"حدد النون أو التنوين ثم الحرف التالي، واقرأ المثال مع غنة معتدلة من غير مبالغة.","إظهار النون مستقلة أو حذف الغنة تمامًا أو إطالتها تكلفًا.","تحفة الأطفال، باب أحكام النون الساكنة والتنوين؛ شروحها."),
  TajweedLesson(12,"الإدغام بغير غنة","أن يطبق المتعلم الإدغام عند اللام والراء.","هو إدخال النون الساكنة أو التنوين في اللام أو الراء دون إبقاء غنة النون.","حرفاه اللام والراء، ويكون الإدغام عند التقاء النون الساكنة أو التنوين بأحدهما في كلمتين.",listOf("مِنْ رَبِّهِمْ","مِنْ لَدُنْهُ","هُدًى لِلْمُتَّقِينَ"),"اقرأ الأمثلة مع إدغام النون في اللام أو الراء دون غنة زائدة.","إظهار النون قبل اللام أو الراء، أو إضافة غنة ليست من هذا الحكم.","تحفة الأطفال، باب أحكام النون الساكنة والتنوين."),
  TajweedLesson(13,"الإظهار المطلق","أن يعرف المتعلم مواضع الإظهار المطلق المشهورة.","الإظهار المطلق هو إظهار النون الساكنة إذا جاء بعدها ياء أو واو في الكلمة نفسها، منعًا للإدغام.","ورد في كلمات معدودة مشهورة: الدنيا، بنيان، صنوان، قنوان؛ فلا تدغم النون في الياء أو الواو هنا لاتحاد الكلمة.","الدُّنْيَا؛ بُنْيَان؛ صِنْوَان؛ قِنْوَان.","تأمل موضع النون في الكلمات الأربع، وانطقها ظاهرة ثم قارنها بإدغام كلمتين.","تطبيق الإدغام لمجرد مجيء ياء أو واو بعد النون دون مراعاة كونها في كلمة واحدة.","كتب التجويد، باب الإظهار المطلق في أحكام النون الساكنة."),
  TajweedLesson(14,"الإقلاب","أن يتعرف المتعلم حرف الإقلاب وطريقة أدائه.","الإقلاب هو قلب النون الساكنة أو التنوين ميمًا مخفاة عند الباء مع الغنة.","حرفه الباء فقط؛ وتكون الميم مخفاة مع مراعاة الغنة وعدم إطباق الشفتين إطباقًا شديدًا يعوق الخفاء.","مِنْ بَعْدِ؛ سَمِيعٌ بَصِيرٌ؛ أَنْبِئْهُمْ.","استخرج الباء بعد النون أو التنوين، ثم تدرب على صوت الميم المخفاة بإشراف معلّم.","إظهار النون بدل قلبها ميمًا، أو تحويل الميم إلى باء، أو المبالغة في الإخفاء.","تحفة الأطفال، باب أحكام النون الساكنة والتنوين."),
  TajweedLesson(15,"الإخفاء الحقيقي","أن يحفظ المتعلم حروف الإخفاء ويعرف فكرته.","الإخفاء الحقيقي حالة بين الإظهار والإدغام، مع بقاء الغنة.","حروفه خمسة عشر: ص ذ ث ك ج ش ق س د ط ز ف ت ض ظ؛ ويكون عند وقوع أحدها بعد النون الساكنة أو التنوين.","مِنْ صَلْصَالٍ؛ أَنْفُسَكُمْ؛ مِنْ تَحْتِهَا؛ قَوْمًا ظَالِمِينَ.","اقرأ أمثلة متنوعة، وحدد حرف الإخفاء، وانتبه إلى قرب اللسان من مخرج الحرف التالي دون نطق نون كاملة.","تحويل الإخفاء إلى إظهار واضح أو إدغام كامل، أو جعل الغنة طويلة على نحو متكلف.","تحفة الأطفال وشروحها، باب الإخفاء."),
  TajweedLesson(16,"الميم الساكنة وأحكامها","أن يميز المتعلم أحكام الميم الساكنة الثلاثة.","الميم الساكنة هي الميم الخالية من الحركة، ولها أحكام بحسب الحرف الذي يأتي بعدها.","أحكامها: الإخفاء الشفوي عند الباء، والإدغام الشفوي عند الميم، والإظهار الشفوي عند بقية الحروف.","تَرْمِيهِمْ بِحِجَارَةٍ؛ لَهُمْ مَا؛ أَنْعَمْتَ عَلَيْهِمْ.","ضع خطًا تحت الميم الساكنة، ثم صنف الحرف التالي إلى باء أو ميم أو غيرهما.","الخلط بين أحكام الميم الساكنة وأحكام النون الساكنة والتنوين.","تحفة الأطفال، باب أحكام الميم والنون المشددتين والميم الساكنة."),
  TajweedLesson(17,"الإخفاء الشفوي","أن يؤدي المتعلم الميم الساكنة قبل الباء.","الإخفاء الشفوي هو إخفاء الميم الساكنة عند الباء مع بقاء الغنة.","حرفه الباء، ويكون بإخفاء الميم عندها مع غنة، ويؤخذ ضبطه بالمشافهة.","تَرْمِيهِمْ بِحِجَارَةٍ؛ وَمَا هُمْ بِمُؤْمِنِينَ.","كرر المثال ببطء، ولاحظ بقاء الغنة مع عدم فصل الميم عن الباء فصلًا ظاهرًا.","إظهار الميم إظهارًا كاملًا أو إدغامها في الباء.","تحفة الأطفال، باب أحكام الميم الساكنة."),
  TajweedLesson(18,"الإدغام الشفوي","أن يطبق المتعلم إدغام الميم الساكنة في الميم المتحركة.","الإدغام الشفوي هو إدخال الميم الساكنة في الميم التي بعدها لتصبحا ميمًا مشددة.","يكون إذا جاءت ميم متحركة بعد ميم ساكنة، مع غنة ظاهرة منضبطة.","لَهُمْ مَا يَشَاءُونَ؛ كَمْ مِنْ فِئَةٍ.","اقرأ المثال مع ملاحظة تشديد الميم الناتجة وغنتها، دون تكرار إغلاق الشفتين مرتين.","إظهار الميمين منفصلتين أو إسقاط التشديد والغنة.","تحفة الأطفال، باب أحكام الميم الساكنة."),
  TajweedLesson(19,"الإظهار الشفوي","أن يميز المتعلم إظهار الميم الساكنة عند غير الباء والميم.","الإظهار الشفوي هو نطق الميم الساكنة واضحة عند حروف الهجاء عدا الباء والميم.","تظهر الميم عند بقية الحروف، ويجب الانتباه خاصة عند الواو والفاء لقرب المخرج.","أَنْعَمْتَ عَلَيْهِمْ؛ هُمْ فِيهَا؛ أَمْ لَمْ.","اقرأ أمثلة تتلو فيها الميم الساكنة فاءً أو واوًا أو غيرهما، وأظهر الميم من غير مبالغة.","إخفاء الميم عند الفاء أو الواو أو إدغامها فيما بعدها.","تحفة الأطفال وشروحها، باب أحكام الميم الساكنة."),
  TajweedLesson(20,"النون والميم المشددتان","أن يضبط المتعلم الغنة في النون والميم المشددتين.","الغنة صوت يخرج من الخيشوم، وتلازم النون والميم، وتظهر بوضوح في المشددتين.","يجب إظهار الغنة في النون والميم المشددتين بمقدار حركتين في رواية حفص من طريق الشاطبية، مع تلقي الأداء.","إِنَّ؛ ثُمَّ؛ عَمَّ؛ النَّاس.","اقرأ الكلمات منفردة ثم في سياقها، وحافظ على غنة متزنة دون ضغط أو مبالغة.","إضعاف الغنة أو تطويلها أكثر من اللازم أو تحويلها إلى صوت أنفي متكلف.","تحفة الأطفال، باب أحكام الميم والنون المشددتين؛ المقدمة الجزرية.")
)
